def subarraySum(nums, k):
    count, curr_sum = 0, 0
    prefix_map = {0: 1}
    for n in nums:
        curr_sum += n
        diff = curr_sum - k
        if diff in prefix_map: count += prefix_map[diff]
        prefix_map[curr_sum] = prefix_map.get(curr_sum, 0) + 1
    return count

