def decodeString(s):
    num_stack, str_stack = [], []
    curr_num, curr_str = 0, ""
    for ch in s:
        if ch.isdigit(): curr_num = curr_num * 10 + int(ch)
        elif ch == "[":
            num_stack.append(curr_num)
            str_stack.append(curr_str)
            curr_num, curr_str = 0, ""
        elif ch == "]":
            k = num_stack.pop()
            prev = str_stack.pop()
            curr_str = prev + curr_str * k
        else: curr_str += ch
    return curr_str

