def nextGreaterElement(nums1, nums2):
    mapping = {}
    stack = []
    for n in nums2:
        while stack and n > stack[-1]:
            mapping[stack.pop()] = n
        stack.append(n)
    return [mapping.get(n, -1) for n in nums1]

