class TimeMap:
    def __init__(self):
        self.store = {}
    def set(self, key, value, timestamp):
        if key not in self.store: self.store[key] = []
        self.store[key].append((timestamp, value))
    def get(self, key, timestamp):
        res = ""
        values = self.store.get(key, [])
        l, r = 0, len(values) - 1
        while l <= r:
            m = (l + r) // 2
            if values[m][0] <= timestamp:
                res = values[m][1]
                l = m + 1
            else: r = m - 1
        return res

